#!/usr/bin/env python3
"""Regular expressions: ~r, =~, the Regex module and the String functions that
take a regex (spec/alchem-regex.md). Every program runs as the pinned compiler
runs it: programs written out, and 468 generated patterns each tried on a
subject through match?, run, scan, split, replace (a template, a function of
the match and one of its groups) and named_captures, a ~r compiled with the
program where it can be written as one and Regex.compile otherwise. Programs
that end with a failure are among them, with its trace."""
from pathlib import Path
import subprocess
import sys
import tempfile

